<?php

namespace App\Support;

/**
 * ToolSeo — server-rendered SEO/GEO layer for /tools/* pages.
 *
 * Same contract as MarketingSeo::pages(): keyed by ROUTE NAME, each entry
 * needs title / description / keywords / jsonld / static_html. Merged into
 * MarketingSeo::pages() (see that class) so app.blade.php needs no changes.
 *
 * See SEO/SEO Tools/VENQORE_FREE_TOOLS_IMPLEMENTATION_PLAN.md §4.7.
 *
 * RULE: every route registered under the `tools.` prefix in routes/web.php
 * MUST have an entry here before merge. tests/Feature/Tools/ToolSeoCoverageTest.php
 * enforces this — a tool page with no entry is invisible to GPTBot,
 * ClaudeBot and PerplexityBot (none of them execute the client-rendered
 * React bundle), which defeats the entire point of this program.
 *
 * Do NOT add AggregateRating schema anywhere in this file. app.blade.php
 * already carries a comment explaining why a fabricated rating block was
 * removed site-wide — Google treats unsubstantiated review/rating markup
 * as a policy violation. We have no real review data for these tools.
 */
class ToolSeo
{
    /** @return array<string, array> */
    public static function pages(): array
    {
        $nav = self::toolsNav();
        return array_merge(            self::hubPage($nav),            self::barcodePages($nav),            self::invoicePages($nav),            self::receiptPages($nav),            self::priceTagPages($nav),            self::labelSheetPages($nav),            self::marginCalculatorPages($nav),            self::inventoryHealthPages($nav),            self::skuGeneratorPages($nav),            self::qrCodePages($nav),            self::qrMenuPages($nav),            self::stockCountPages($nav),            self::purchaseOrderPages($nav),            self::packingSlipPages($nav),            self::quotationPages($nav),            self::creditNotePages($nav),            self::csvCleanerPages($nav),            self::cashDrawerPages($nav),            self::paymentFeePages($nav),            self::posRoiPages($nav),            self::foodCostPages($nav),            self::barcodeLabelSheetPages($nav),        );    }


    private static function toolsNav(): string
    {
        return '<nav><a href="/tools">All Tools</a> · <a href="/tools/barcode-generator">Barcode Generator</a> · '            . '<a href="/tools/barcode-validator">Barcode Validator</a> · <a href="/pricing">Pricing</a> · '            . '<a href="/demo">Live Demo</a></nav>';    }

    private static function toolCta(string $productNoun): string
    {
        return '<p><strong>Stop doing this manually.</strong> VenQore generates ' . $productNoun            . ' automatically on every product — and writes a balanced double-entry journal on every sale. '            . '<a href="/pricing"><strong>Start your 14-day free trial</strong></a> · <a href="/demo">Try the live demo, no signup</a></p>';    }

    private static function softwareApplicationLd(string $name, string $url, string $description): array
    {
        return [            '@type'               => 'SoftwareApplication',            'name'                => $name,            'applicationCategory' => 'BusinessApplication',            'operatingSystem'     => 'Web browser',            'url'                 => $url,            'description'         => $description,            'offers'              => ['@type' => 'Offer', 'price' => '0', 'priceCurrency' => 'USD'],        ];
    }

    private static function breadcrumbLd(array $crumbs): array
    {
        // $crumbs = [['name' => 'Tools', 'url' => url('/tools')], ...]
        return [            '@type'           => 'BreadcrumbList',            'itemListElement' => array_map(
                fn ($crumb, $i) => [
                    '@type'    => 'ListItem',
                    'position' => $i + 1,
                    'name'     => $crumb['name'],
                    'item'     => $crumb['url'],
                ],
                $crumbs,
                array_keys($crumbs)
            ),
        ];
    }

    private static function faqLd(array $qas): array
    {
        return [            '@type'      => 'FAQPage',            'mainEntity' => array_map(fn ($qa) => [                '@type'          => 'Question',                'name'           => $qa[0],                'acceptedAnswer' => ['@type' => 'Answer', 'text' => $qa[1]],            ], $qas),        ];
    }

    // ── /tools hub ─────────────────────────────────────

    private static function hubPage(string $nav): array
    {
        return [            'tools.index' => [                'title'       => 'Free Retail Tools — Barcode Generator & More | VenQore',                'description' => 'Free tools for retail and small business: barcode generator, label sheets, invoice templates and more. No signup required, no watermark.',                'keywords'    => 'free retail tools, free barcode generator, free invoice generator, small business tools',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                            ]),                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<h1>Free Retail Tools</h1>'                    . '<p><strong>Free, practical tools for retail and small business owners — no signup, no watermark.</strong> Built by the team behind VenQore, an offline-first POS and ERP with verified double-entry accounting.</p>'                    . '<h2>Available now</h2>'                    . '<ul><li><a href="/tools/barcode-generator"><strong>Barcode Generator</strong></a> — Code128, EAN-13, UPC-A, Code39, ITF-14 and more, as PNG or SVG</li>'                    . '<li><a href="/tools/barcode-validator"><strong>Barcode Validator</strong></a> — check-digit verification for EAN/UPC/GTIN codes</li></ul>'                    . $nav . '</main>',            ],        ];
    }

    // ── T1 Barcode Generator + 9 format children + T10 Validator ─────────────────────────────────────

    private static function barcodeFormats(): array
    {
        // slug => [display name, symbol set summary, length rule, typical retail use, extra fact]
        return [            'code128' => ['Code128', 'full ASCII (128 characters)', 'variable length', 'shipping labels, internal inventory codes, serial numbers', 'the most information-dense 1D barcode in common retail use — it can encode letters, numbers and punctuation in one symbol.'],            'code39'  => ['Code39', 'uppercase letters, digits, and - . $ / + % space', 'variable length', 'inventory tracking, asset tags, automotive and defense industries', 'one of the oldest alphanumeric barcode standards, still widely supported by legacy scanners.'],            'code93'  => ['Code93', 'full ASCII, more compact than Code39', 'variable length', 'package identification, postal services, inventory', 'a denser successor to Code39 used where label space is limited.'],            'ean-13'  => ['EAN-13', 'digits only', '12 digits + 1 check digit = 13', 'retail point-of-sale worldwide (the barcode on nearly every packaged product)', 'the international standard for retail product identification outside North America.'],            'ean-8'   => ['EAN-8', 'digits only', '7 digits + 1 check digit = 8', 'small packaging where a full EAN-13 will not fit, e.g. cosmetics, cigarettes', 'a compressed EAN variant for physically small products.'],            'upc-a'   => ['UPC-A', 'digits only', '11 digits + 1 check digit = 12', 'retail point-of-sale in the United States and Canada', 'the standard retail barcode across North American grocery and general retail.'],            'upc-e'   => ['UPC-E', 'digits only', '6 digits (zero-suppressed) + check digit', 'small retail packaging in North America', 'a compressed form of UPC-A for products too small for the full 12-digit symbol.'],            'itf-14'  => ['ITF-14', 'digits only', '13 digits + 1 check digit = 14', 'shipping cartons and case-level packaging, not individual retail items', 'used on outer cases and pallets — one level up from the EAN-13/UPC-A on the individual product.'],            'codabar' => ['Codabar', 'digits and - $ : / . +', 'variable length', 'blood banks, libraries, older parcel and film-processing systems', 'still common in healthcare and library systems despite being an older standard.'],        ];
    }

    private static function barcodePages(string $nav): array
    {
        $pages = [];
        $formats = self::barcodeFormats();
        $formatTableRows = '';
        foreach ($formats as $slug => [$name, $charset, $length, $use]) {
            $formatTableRows .= "<tr><td>{$name}</td><td>{$charset}</td><td>{$length}</td><td>{$use}</td></tr>";        }
        $barcodeFaqs = [            ['What is a barcode generator?', 'A barcode generator converts a number or text value into a scannable barcode image (like Code128 or EAN-13) that a barcode scanner or point-of-sale system can read back into that original value.'],            ['Is the VenQore barcode generator really free?', 'Yes. Generating and downloading a single barcode in any supported format is completely free, with no signup and no watermark. An email is only requested for bulk generation of more than 10 codes at once.'],            ['Which barcode format should I use for retail products?', 'Use EAN-13 if you sell internationally or outside North America, and UPC-A if you sell primarily in the United States or Canada. Use Code128 for internal inventory codes, asset tags, or anything that is not a retail point-of-sale product.'],            ['What resolution should I use for printed barcodes?', 'Use 300 DPI for barcodes that will be printed and scanned physically. Lower resolutions like 72 DPI are fine for on-screen or digital use only.'],            ['Does the generator calculate the check digit for me?', 'Yes. For EAN-8, EAN-13, UPC-A, UPC-E and ITF-14, you can enter the value without a check digit and the VenQore Barcode Generator computes and displays it automatically.'],            ['Can I generate barcodes in bulk?', 'Yes — paste a list of values or upload a CSV to generate more than 10 barcodes at once. Bulk generation requires an email address so we can send you the ZIP file and print-ready PDF sheet.'],        ];
