                              ['@type' => 'HowToStep', 'name' => 'Add line items', 'text' => 'List each product or service with quantity, unit price, and optional per-line tax and discount.'],                                    ['@type' => 'HowToStep', 'name' => 'Choose a template and download', 'text' => 'Pick from four templates, then download the finished PDF — free, unwatermarked, ready to send.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Invoice Generator</nav>'                    . '<h1>Free Invoice Generator</h1>'                    . '<p><strong>Create a professional, unwatermarked PDF invoice in minutes.</strong> Choose from four templates, bill in 10 currencies, and apply tax or discounts to individual line items. No signup required, and your company profile is saved locally so you never retype it.</p>'                    . '<h2>What you can customize</h2>'                    . '<ul><li>Company logo, name, address, email, phone and tax ID</li>'                    . '<li>Unlimited line items with per-line quantity, unit price, discount % and tax %</li>'                    . '<li>Invoice number, issue date, due date, notes and payment terms</li>'                    . '<li>Four visual templates: Clean, Modern, Classic, Compact</li>'                    . '<li>10 supported currencies</li></ul>'                    . '<h2>How to create an invoice</h2>'                    . '<ol><li>Add your company details — saved locally for next time.</li><li>Add the client you are billing.</li><li>Add line items with quantity, price, tax and discount.</li><li>Pick a template and download the PDF.</li></ol>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $invoiceFaqs))                    . self::toolCta('invoices')                    . '<p>Related: <a href="/tools/barcode-generator">Barcode Generator</a></p>'                    . $nav . '</main>',            ],        ];
