        $receiptFaqs = [            ['Is the VenQore receipt generator really free?', 'Yes. Creating and downloading a PDF receipt is completely free, with no signup, no watermark and no limit on the number of receipts you generate.'],            ['Can I print it on my thermal receipt printer?', 'Yes — choose the 80mm Thermal Roll paper size and the PDF is sized to match standard 80mm thermal printer rolls, with a generous page height since most thermal printers cut per receipt automatically.'],            ['What if I don\'t have a thermal printer?', 'Use the Standard Letter/A4 preset. It prints on any regular printer or saves as a normal-size PDF for emailing or filing, with the receipt content kept in a narrow column that mirrors a real receipt layout.'],            ['Can I show change due for cash payments?', 'Yes — when you select Cash as the payment method, enter the amount tendered and the tool calculates and prints the change due automatically. Card and Other payment methods hide that section since it does not apply.'],            ['Can I add a returns policy note?', 'Yes — set "Returns accepted within N days" and the receipt prints a line such as "Returns accepted within 30 days with this receipt" at the bottom, right above the footer.'],            ['Does it support a single overall discount and tax rate?', 'Yes. Unlike the invoice generator, the receipt generator uses one overall tax rate and one overall discount (either a flat amount or a percentage) applied to the whole sale, matching how most point-of-sale receipts total out.'],            ['Is my receipt data stored anywhere?', 'No. The PDF is generated on request and streamed back to you immediately. Nothing about the receipt — store details, line items, or totals — is saved on our servers.'],        ];
        return [            'tools.receipt' => [                'title'       => 'Free Receipt Generator — Thermal & PDF | VenQore',                'description' => 'Create a free POS receipt as PDF. 80mm thermal roll or Letter/A4 for records, overall tax and discount, cash change due. No signup, no watermark.',                'keywords'    => 'free receipt generator, receipt maker online, pos receipt template, thermal receipt printer pdf, print receipt free, cash receipt generator',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Receipt Generator',                                url('/tools/receipt-generator'),                                'Free online point-of-sale receipt generator producing an unwatermarked PDF sized for 80mm thermal printers or Letter/A4 record-keeping, with overall tax, discount and cash change-due calculation.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Receipt Generator', 'url' => url('/tools/receipt-generator')],                            ]),                            self::faqLd($receiptFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to create a free POS receipt PDF',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Add your store details', 'text' => 'Enter your store name, address, phone and optionally a logo and a thank-you footer message. These are saved in your browser for next time.'],                                    ['@type' => 'HowToStep', 'name' => 'Add line items', 'text' => 'List each product sold with quantity and unit price.'],                                    ['@type' => 'HowToStep', 'name' => 'Set tax, discount and payment', 'text' => 'Enter one overall tax rate, an optional flat or percentage discount, and the payment method — cash entries also show amount tendered and change due.'],                                    ['@type' => 'HowToStep', 'name' => 'Choose a paper size and download', 'text' => 'Pick 80mm Thermal Roll for a receipt printer or Standard Letter/A4 for records, then download the finished PDF — free, unwatermarked, ready to print.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Receipt Generator</nav>'                    . '<h1>Free Receipt Generator</h1>'                    . '<p><strong>Create a professional, unwatermarked point-of-sale receipt as a PDF in minutes.</strong> Print it directly on an 80mm thermal receipt printer, or generate a Letter/A4-size copy for filing and email. No signup required, and your store profile is saved locally so you never retype it.</p>'                    . '<h2>What you can customize</h2>'                    . '<ul><li>Store logo, name, address and phone number</li>'                    . '<li>Unlimited line items with quantity and unit price</li>'                    . '<li>Receipt number, date/time and optional cashier name</li>'                    . '<li>One overall tax rate and one overall discount (flat amount or percentage)</li>'                    . '<li>Payment method — Cash, Card or Other — with amount tendered and change due for cash sales</li>'                    . '<li>A configurable "Returns accepted within N days" note and a custom thank-you footer message</li>'                    . '<li>Two paper presets: 80mm Thermal Roll or Standard Letter/A4 for records</li></ul>'                    . '<h2>Thermal roll vs. Letter/A4</h2>'                    . '<p>The <strong>80mm Thermal Roll</strong> preset matches the width used by nearly all point-of-sale thermal receipt printers, with a tall fixed page height since most printers cut the paper automatically after each receipt. The <strong>Standard Letter/A4</strong> preset prints on any regular printer or saves as a normal-size PDF, with the receipt content laid out in a narrow column so it still reads like a real receipt.</p>'                    . '<h2>How to create a receipt</h2>'                    . '<ol><li>Add your store details — saved locally for next time.</li><li>Add line items with quantity and unit price.</li><li>Set an overall tax rate, discount and payment method.</li><li>Pick a paper size and download the PDF.</li></ol>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $receiptFaqs))                    . self::toolCta('receipts')                    . '<p>Related: <a href="/tools/invoice-generator">Invoice Generator</a> · <a href="/tools/barcode-generator">Barcode Generator</a></p>'                    . $nav . '</main>',            ],        ];
    }

