        $priceTagFaqs = [            ['Is the VenQore price tag generator really free?', 'Yes. Building and downloading a print-ready PDF of shelf-edge price tags is completely free, with no signup and no watermark, for any number of products within the rate limit.'],            ['Can I print tags for many different products at once?', 'Yes — that is the whole point of this tool. Add or paste as many rows as you like, each with its own name and price, and every row becomes one distinct tag on the sheet. This is different from a barcode print-sheet, which repeats a single value.'],            ['What is the fastest way to enter a lot of products?', 'Use the bulk paste box. Paste one product per line as name,price or name,price,was_price,sku,badge — the tool parses it straight into the row list, so you can build a 100-tag sheet from a spreadsheet in seconds.'],            ['Can I show a "was" price with a strikethrough for sale items?', 'Yes. Add a "was" price to any row and the tag prints the old price with a strikethrough next to a larger, bolder current price, with an optional SALE/CLEARANCE badge in the corner.'],            ['Does the price tag include a barcode?', 'Optionally. Turn on the barcode toggle and give each row a SKU — the tag embeds a small Code128 barcode alongside the price so it can double as a scannable shelf label.'],            ['What label sizes are supported?', 'Small thermal shelf-tag sizes (40×30 mm, 50×25 mm, 50×30 mm, 60×40 mm) for direct label printers, plus Avery-compatible A4 and Letter sheet grids (21, 24 or 65 tags per sheet) for a standard printer.'],            ['Can I print multiple copies of the same batch?', 'Yes — set the copies multiplier to print the whole batch of tags more than once, useful for stocking the same product range on two shelves or two store locations.'],        ];
        return [            'tools.price-tag' => [                'title'       => 'Free Price Tag Generator — Shelf Labels PDF | VenQore',                'description' => 'Create print-ready shelf-edge price tags for many products at once, free. Sale pricing, badges, optional barcodes, thermal and A4/Letter label sizes. No signup.',                'keywords'    => 'free price tag generator, shelf price tag maker, retail price label generator, sale tag printer, shelf edge label pdf, price tag template free',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Price Tag Generator',                                url('/tools/price-tag-generator'),                                'Free online price tag generator that builds a print-ready PDF sheet of shelf-edge price tags for many different products at once, with sale pricing, badges and optional barcodes.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Price Tag Generator', 'url' => url('/tools/price-tag-generator')],                            ]),                            self::faqLd($priceTagFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to print a sheet of shelf price tags',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Add your products', 'text' => 'Enter each product name and price as a row, or paste a CSV-style list (name,price,was_price,sku,badge) into the bulk paste box to add many at once.'],                                    ['@type' => 'HowToStep', 'name' => 'Mark down sale items', 'text' => 'Add a was-price to any row to show a strikethrough old price next to the new price, and pick a quick badge like SALE or CLEARANCE.'],                                    ['@type' => 'HowToStep', 'name' => 'Choose a label size', 'text' => 'Pick a thermal shelf-tag size for a label printer, or an Avery-compatible A4/Letter grid for a standard printer.'],                                    ['@type' => 'HowToStep', 'name' => 'Download and print', 'text' => 'Download the PDF and print at 100% / "Actual size" so the tags line up with your label stock.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Price Tag Generator</nav>'                    . '<h1>Free Price Tag Generator</h1>'                    . '<p><strong>The VenQore Price Tag Generator builds a print-ready PDF sheet of shelf-edge price tags for many different products at once.</strong> Unlike a barcode print-sheet that repeats one value, every row you add or paste — product name, price, optional sale price, SKU and badge — becomes its own tag on the sheet. Free, no signup, no watermark.</p>'                    . '<h2>Two ways to add products</h2>'                    . '<ul><li><strong>Manual entry</strong> — add rows one at a time with name, price, optional "was" price, SKU/barcode value and a badge like SALE or NEW.</li>'                    . '<li><strong>Bulk paste</strong> — paste a CSV-style list, one product per line, as <code>name,price</code> or <code>name,price,was_price,sku,badge</code>, and the tool parses it straight into the row list.</li></ul>'                    . '<h2>Sale pricing and badges</h2>'                    . '<p>Add a "was" price to any row to print it with a strikethrough next to a larger, bolder current price — the standard shelf-tag markdown treatment — with an optional colored corner badge such as SALE, NEW, CLEARANCE or HOT DEAL.</p>'                    . '<h2>Optional barcodes</h2>'                    . '<p>Turn on the barcode toggle and give a row a SKU to embed a small scannable Code128 barcode on the tag itself, so the same label works at the shelf edge and at the register.</p>'                    . '<h2>Label sizes</h2>'                    . '<p>Thermal shelf-tag sizes (40×30 mm, 50×25 mm, 50×30 mm, 60×40 mm) for direct label printers, plus Avery-compatible A4 and Letter sheet grids (21, 24 or 65 tags per sheet) for any standard printer.</p>'                    . '<h2>How to print a sheet of price tags</h2>'                    . '<ol><li>Add products manually or paste a CSV-style list.</li><li>Mark down any sale items with a was-price and a badge.</li><li>Choose a thermal or A4/Letter label size.</li><li>Download the PDF and print at 100% scale.</li></ol>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $priceTagFaqs))                    . self::toolCta('shelf-edge price tags')                    . '<p>Related: <a href="/tools/barcode-generator">Barcode Generator</a></p>'                    . $nav . '</main>',            ],        ];
    }

