    }

    // ── Purchase Order Generator ─────────────────────────────────────

    private static function purchaseOrderPages(string $nav): array
    {
        $poFaqs = [            ['Is the VenQore purchase order generator really free?', 'Yes. Creating and downloading a PDF purchase order is completely free, with no signup, no watermark and no limit on the number of purchase orders you generate.'],            ["What's the difference between a purchase order and an invoice?", 'A purchase order (PO) is issued by the buyer BEFORE goods ship, as a formal request to a supplier stating what is being ordered, in what quantity, and at what price. An invoice is issued by the seller AFTER — or upon — fulfillment, requesting payment for what was actually delivered. The PO initiates the order; the invoice bills for it.'],            ['Do I need a purchase order for small purchases?', "It's optional for very small or one-off buys, but a PO habit pays off even for small retailers: it creates a written paper trail of what was ordered and at what price, protects you if a supplier ships the wrong quantity or invoices a different price than agreed, and makes month-end accounting reconciliation far easier."],            ['Is a purchase order legally binding?', 'Once a supplier accepts it — verbally, in writing, or simply by shipping the goods — a purchase order generally functions as a binding contract for the price and quantity stated, much like any other written offer that has been accepted. Exact enforceability depends on your jurisdiction and any terms and conditions referenced on the PO.'],            ['Can I save my business details for next time?', 'Yes — your business name, address, logo and tax ID are saved in your browser so you do not have to retype them on your next purchase order. Nothing is sent to or stored on our servers.'],            ['Does it support a separate Ship To address?', 'Yes. Purchase orders often need to ship to a warehouse or receiving dock different from your billing address — add an optional Ship To block, separate from your business address.'],            ['Can I reference a supplier SKU on each line?', 'Yes — each line item has an optional SKU/item code column so you can reference the supplier\'s own catalog number alongside your description, reducing the chance of the wrong item being picked and shipped.'],            ['Is my purchase order data stored anywhere?', 'No. The PDF is generated on request and streamed back to you immediately. Nothing about the purchase order — business, supplier, or line items — is saved on our servers.'],        ];
        return [            'tools.purchase-order' => [                'title'       => 'Free Purchase Order Generator — PDF, No Watermark | VenQore',                'description' => 'Create a professional PDF purchase order free online. Multiple templates, multi-currency, ship-to address, supplier SKUs and signature line. No signup, no watermark.',                'keywords'    => 'free purchase order generator, purchase order template pdf, po generator online, create purchase order free, purchase order maker no signup',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Purchase Order Generator',                                url('/tools/purchase-order-generator'),                                'Free online purchase order generator with multiple templates, multi-currency support, ship-to address, supplier SKU column and an authorized-by signature line, producing an unwatermarked PDF.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Purchase Order Generator', 'url' => url('/tools/purchase-order-generator')],                            ]),                            self::faqLd($poFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to create a free PDF purchase order',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Add your business details', 'text' => 'Enter your business name, address, and optionally a logo and tax ID. These are saved in your browser for next time.'],                                    ['@type' => 'HowToStep', 'name' => 'Add the supplier', 'text' => 'Enter the name, contact person and address of the supplier you are ordering from, and an optional Ship To address if goods go to a different location.'],                                    ['@type' => 'HowToStep', 'name' => 'Add line items', 'text' => 'List each product with an optional supplier SKU, quantity, unit price and optional per-line tax.'],                                    ['@type' => 'HowToStep', 'name' => 'Set terms and download', 'text' => 'Add shipping and payment terms, an optional authorized-by name for the signature line, pick a template, then download the finished PDF — free, unwatermarked, ready to send.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Purchase Order Generator</nav>'                    . '<h1>Free Purchase Order Generator</h1>'                    . '<p><strong>Create a professional, unwatermarked PDF purchase order in minutes.</strong> Choose from four templates, order in 10 currencies, reference supplier SKUs per line, and add a Ship To address separate from your billing address. No signup required, and your business profile is saved locally so you never retype it.</p>'                    . '<h2>What is a purchase order?</h2>'                    . '<p>A purchase order (PO) is a document a buyer sends to a supplier to formally request goods — listing what is being ordered, the quantity, the agreed price, and where it should ship. It is issued <strong>before</strong> the order is fulfilled. Small retailers benefit from using POs even for routine restocking: it creates a paper trail that protects both sides if there is a dispute over quantity or price, and it gives your bookkeeping a clean reference to match against the supplier\'s invoice and the goods you actually receive.</p>'                    . '<h2>Purchase order vs. invoice</h2>'                    . '<p>These are opposite ends of the same transaction. A <strong>purchase order</strong> is issued by the <strong>buyer</strong>, before the goods ship, as a request. An <strong>invoice</strong> is issued by the <strong>seller</strong>, after or upon fulfillment, as a bill. If you are ordering stock from a supplier, you issue a PO. If you are the one getting paid for something you sold, use the <a href="/tools/invoice-generator">Invoice Generator</a> instead.</p>'                    . '<h2>What you can customize</h2>'                    . '<ul><li>Business logo, name, address, email, phone and tax ID</li>'                    . '<li>Supplier name, contact person, address and email</li>'                    . '<li>Optional Ship To address, separate from your billing address</li>'                    . '<li>Unlimited line items with optional SKU/item code, quantity, unit price and per-line tax %</li>'                    . '<li>PO number, PO date, requested delivery date</li>'                    . '<li>Shipping/freight terms (e.g. FOB Origin) and payment terms (e.g. Net 30)</li>'                    . '<li>An Authorized By signature line for a physical/print signature</li>'                    . '<li>Four visual templates: Clean, Modern, Classic, Compact</li>'                    . '<li>10 supported currencies</li></ul>'                    . '<h2>How to create a purchase order</h2>'                    . '<ol><li>Add your business details — saved locally for next time.</li><li>Add the supplier you are ordering from, and a Ship To address if needed.</li><li>Add line items with SKU, quantity, price and tax.</li><li>Set shipping and payment terms, pick a template, and download the PDF.</li></ol>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $poFaqs))                    . self::toolCta('purchase orders')                    . '<p>Related: <a href="/tools/invoice-generator">Invoice Generator</a> · <a href="/tools/barcode-generator">Barcode Generator</a></p>'                    . $nav . '</main>',            ],        ];
    }

    // ── Packing Slip Generator ─────────────────────────────────────

    private static function packingSlipPages(string $nav): array
    {
        $packingSlipFaqs = [            ['Does a packing slip need prices?', 'No. A packing slip traditionally carries no pricing at all — no unit price, no tax, no total. It travels inside the box to tell whoever opens it what is inside, not what is owed. This tool has no price fields anywhere in its data model, so pricing can never end up on the PDF.'],            ["What's the difference between a packing slip and an invoice?", 'An invoice is a bill: it lists prices, tax and a total amount owed, and is sent to whoever pays. A packing slip is a shipping document: it lists what was ordered and what was actually shipped, with zero pricing, and physically ships inside the box with the goods rather than being billed to the customer.'],            ['Do I need a packing slip for every shipment?', "It isn't legally required in most cases, but it's standard retail and e-commerce practice. It helps the recipient verify contents on arrival, gives warehouse and receiving staff a price-free reference (useful when the person opening the box isn't the buyer), and makes partial shipments and returns far easier to reconcile."],            ['What is a partial shipment and how is it shown?', 'A partial shipment happens when the quantity shipped is less than the quantity ordered on one or more lines — common when an item is backordered. This tool compares Qty Ordered to Qty Shipped on every line automatically and prints a clear "this is a partial shipment — remaining items will ship separately" notice on the PDF, with no manual toggle required.'],            ['Is the packing slip generator really free?', 'Yes. Creating and downloading a PDF packing slip is completely free, with no signup, no watermark and no limit on the number you generate.'],            ['Can I save my business details for next time?', 'Yes — your ship-from business name, address and logo are saved in your browser so you do not have to retype them next time. Nothing is sent to or stored on our servers until you click Download.'],            ['Can I track quantity ordered vs. quantity shipped separately?', 'Yes — every line item has its own Qty Ordered and Qty Shipped fields, so you can print an accurate slip even when a shipment is only partially fulfilled.'],        ];
        return [            'tools.packing-slip' => [                'title'       => 'Free Packing Slip Generator — PDF, No Prices | VenQore',                'description' => "Create a free PDF packing slip online. No prices or totals — just what's inside the box, with automatic partial-shipment detection. No signup, no watermark.",                'keywords'    => 'free packing slip generator, packing slip template pdf, packing slip maker online, packing list generator, shipping slip no prices, partial shipment packing slip',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Packing Slip Generator',                                url('/tools/packing-slip-generator'),                                'Free online packing slip generator with ship-from and ship-to addresses, quantity ordered vs. quantity shipped per line, automatic partial-shipment detection, and no pricing fields, producing an unwatermarked PDF.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Packing Slip Generator', 'url' => url('/tools/packing-slip-generator')],                            ]),                            self::faqLd($packingSlipFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to create a free PDF packing slip',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Add your Ship From details', 'text' => 'Enter your business name, address and optionally a logo. These are saved in your browser for next time.'],                                    ['@type' => 'HowToStep', 'name' => 'Add the Ship To address', 'text' => 'Enter the recipient name and shipping address the package is going to.'],                                    ['@type' => 'HowToStep', 'name' => 'Add line items', 'text' => 'List each item with an optional SKU, quantity ordered, and quantity actually shipped. A partial shipment is detected automatically when these differ.'],                                    ['@type' => 'HowToStep', 'name' => 'Choose a template and download', 'text' => 'Pick a template, add an optional carrier, tracking number and special instructions, then download the finished PDF — free, unwatermarked, with no pricing on it.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Packing Slip Generator</nav>'                    . '<h1>Free Packing Slip Generator</h1>'                    . '<p><strong>Create a professional, unwatermarked PDF packing slip in minutes.</strong> A packing slip is the document that ships inside the box — it tells whoever opens it what is inside, not what they owe. No prices, no tax, no totals, ever. No signup required, and your ship-from business profile is saved locally so you never retype it.</p>'                    . '<h2>What is a packing slip?</h2>'                    . '<p>A packing slip (also called a packing list or delivery note) is a shipping document that travels physically inside a package. It lists the items included in the shipment, their SKUs, and the quantity of each — but deliberately <strong>excludes all pricing</strong>. The box might be opened by someone other than the buyer, such as a warehouse receiving clerk, and pricing is often confidential information that has no place in a receiving dock.</p>'                    . '<h2>Packing slip vs. invoice vs. receipt</h2>'                    . '<p>A <strong>packing slip</strong> ships with the goods and has no prices — it is a shipping/fulfillment document. An <strong>invoice</strong> is a bill sent to the customer requesting payment, with prices, tax and a total. A <strong>receipt</strong> confirms a payment already made. If you need to bill a customer, use the <a href="/tools/invoice-generator">Invoice Generator</a> instead — this tool exists purely for what goes in the box.</p>'                    . '<h2>Partial shipments</h2>'                    . '<p>When an order can\'t be fulfilled in full — an item is backordered, out of stock, or split across multiple boxes — the packing slip for each shipment should make that obvious. This tool compares quantity ordered to quantity shipped on every line automatically and prints a clear partial-shipment notice on the PDF whenever they differ, so the recipient knows more is coming and doesn\'t mistake a partial delivery for the whole order.</p>'                    . '<h2>What you can customize</h2>'                    . '<ul><li>Ship From logo, business name, address, email and phone</li>'                    . '<li>Ship To recipient name and address</li>'                    . '<li>Order / reference number, ship date, carrier and tracking number</li>'                    . '<li>Unlimited line items with description, optional SKU, quantity ordered and quantity shipped</li>'                    . '<li>Automatic partial-shipment detection and on-document notice</li>'                    . '<li>Optional special instructions / notes field</li>'                    . '<li>Multiple visual templates, consistent with the rest of the VenQore tools suite</li></ul>'                    . '<h2>How to create a packing slip</h2>'                    . '<ol><li>Add your Ship From business details — saved locally for next time.</li><li>Add the Ship To recipient and address.</li><li>Add line items with quantity ordered and quantity shipped.</li><li>Pick a template and download the PDF — no prices anywhere.</li></ol>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $packingSlipFaqs))                    . self::toolCta('packing slips')                    . '<p>Related: <a href="/tools/invoice-generator">Invoice Generator</a> · <a href="/tools/purchase-order-generator">Purchase Order Generator</a></p>'                    . $nav . '</main>',            ],        ];
    }

    private static function quotationPages(string $nav): array
    {
        $quoteFaqs = [            ['Is the VenQore quotation generator really free?', 'Yes. Creating and downloading a PDF quotation or estimate is completely free, with no signup, no watermark and no limit on how many you generate.'],            ['Is a quote legally binding?', 'Generally no, not on its own — a quotation is an offer, not a signed contract. It typically only becomes binding once the client formally accepts it (a signature, a purchase order, or written confirmation) and, in many jurisdictions, once work begins or a deposit is paid. That is exactly why every quote should carry a validity date and an acceptance section: it makes clear what was offered, at what price, and until when.'],            ['How long should a quote be valid?', 'Most small businesses use 14–30 days. Material costs, labor rates and supplier pricing can shift, so an open-ended quote exposes you to honoring stale pricing indefinitely. This tool defaults every quote to a 30-day validity window from the issue date, automatically calculating the "Valid Until" date — but you can set any period per document.'],            ['What is the difference between a quote, an estimate, and an invoice?', 'A quote (or quotation) is a firm, fixed price offered before work starts — the price should not change once accepted. An estimate is a rough, non-binding approximation given when the full scope is not yet certain, and may move once the job is underway. An invoice is issued after — or during — the work to request payment for what was actually delivered. Quotes and estimates come before the sale; invoices come after. This tool can label the same document either QUOTATION or ESTIMATE.'],            ['Why does a quote need a "Valid Until" date but an invoice does not?', 'An invoice bills for a transaction that has already happened — the price is fixed by what was delivered. A quote is a forward-looking offer for work or goods not yet provided, so the price is only guaranteed for a limited window. Without an expiry date, a customer could try to hold you to a six-month-old price on materials that have since gone up.'],            ['Can I add a discount to help win the deal?', 'Yes — each line item has its own discount percentage in addition to quantity, unit price and tax rate, so you can show a client exactly how much you knocked off list price to win their business.'],            ['Can I list what is included and excluded from the price?', 'Yes — optional Scope of Work / Inclusions and Exclusions sections let you set expectations up front, which matters most for service businesses (contractors, agencies, consultants, trades) where scope creep is the single biggest source of billing disputes.'],            ['Does the quote include a place for the client to accept it?', 'Yes — every generated PDF includes an acceptance section with a short confirmation line and a blank signature/date line, so the client has a clear, printable way to sign off before work begins.'],            ['Is my quotation data stored anywhere?', 'No. The PDF is generated on request and streamed back to you immediately. Nothing about the quotation — company, client, or line items — is saved on our servers.'],        ];
        return [            'tools.quote' => [                'title'       => 'Free Quotation Generator — PDF Quotes & Estimates | VenQore',                'description' => 'Create a professional PDF quotation or estimate free online. Auto valid-until expiry, scope of work, exclusions, per-line tax and discounts, and a client acceptance line. No signup, no watermark.',                'keywords'    => 'free quotation generator, quote generator pdf, estimate template pdf, create a quote free, quotation maker no signup, quote vs invoice, quote vs estimate',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Quotation Generator',                                url('/tools/quote-generator'),                                'Free online quotation and estimate generator with automatic valid-until expiry dates, scope-of-work and exclusions sections, per-line tax and discounts, and a client acceptance/signature block, producing an unwatermarked PDF.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Quotation Generator', 'url' => url('/tools/quote-generator')],                            ]),                            self::faqLd($quoteFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to create a free PDF quotation or estimate',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Add your business details', 'text' => 'Enter your company name, address, and optionally a logo and tax ID. These are saved in your browser for next time.'],                                    ['@type' => 'HowToStep', 'name' => 'Add the client', 'text' => 'Enter the name, address and email of the client the quote is prepared for.'],                                    ['@type' => 'HowToStep', 'name' => 'Add line items and set validity', 'text' => 'List each item with quantity, unit price, optional tax and discount, then set how many days the quote stays valid — the Valid Until date is calculated automatically.'],                                    ['@type' => 'HowToStep', 'name' => 'Set scope and download', 'text' => 'Optionally list what is included and excluded, pick a template, then download the finished PDF — it includes a client acceptance and signature section, free and unwatermarked.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Quotation Generator</nav>'                    . '<h1>Free Quotation Generator</h1>'                    . '<p><strong>Create a professional, unwatermarked PDF quotation or estimate in minutes.</strong> Choose from four templates, quote in 10 currencies, and every document includes an automatic "Valid Until" expiry date so old pricing can never be held against you. No signup required, and your business profile is saved locally so you never retype it.</p>'                    . '<h2>What is a quotation?</h2>'                    . '<p>A quotation (or quote) is a document you send a prospective customer stating the price you will charge for specific goods or work, before that work begins. Unlike an invoice, a quote is an <strong>offer</strong>, not a bill — nothing is owed until the client accepts it.</p>'                    . '<h2>Quote vs. estimate vs. invoice</h2>'                    . '<p>A <strong>quote</strong> is a firm, fixed price that should not change once accepted. An <strong>estimate</strong> is a rough, non-binding approximation used when the full scope is not yet known and may shift once work starts. An <strong>invoice</strong> is issued after — or during — the work to request payment for what was actually delivered. Quotes and estimates come before the sale; invoices come after it. Need to bill for completed work instead? Use the <a href="/tools/invoice-generator">Invoice Generator</a>.</p>'                    . '<h2>Why every quote needs a validity date</h2>'                    . '<p>Material costs, labor rates and supplier pricing move. A quote with no expiry date can leave you honoring stale pricing indefinitely, or in a dispute over what was actually promised. This tool calculates a "Valid Until" date automatically from your issue date plus a validity period (30 days by default, fully editable), and prints it clearly on the PDF.</p>'                    . '<h2>Is a quote legally binding?</h2>'                    . '<p>Usually not until it is accepted. A quotation is an offer; it typically becomes a binding agreement once the client signs it, issues a purchase order, or confirms acceptance in writing — and in many places, once a deposit is paid or work begins. That is why every PDF this tool generates ends with an acceptance section: a confirmation line plus a blank signature and date line for the client to sign off.</p>'                    . '<h2>What you can customize</h2>'                    . '<ul><li>Business logo, name, address, email, phone and tax ID</li>'                    . '<li>Document label — Quotation or Estimate</li>'                    . '<li>Client name, address and email</li>'                    . '<li>Unlimited line items with quantity, unit price, per-line discount % and tax %</li>'                    . '<li>Quote number, issue date, validity period and auto-calculated valid-until date</li>'                    . '<li>Optional Scope of Work / Inclusions and Exclusions sections</li>'                    . '<li>A client acceptance section with a signature and date line</li>'                    . '<li>Four visual templates: Clean, Modern, Classic, Compact</li>'                    . '<li>10 supported currencies</li></ul>'                    . '<h2>How to create a quotation</h2>'                    . '<ol><li>Add your business details — saved locally for next time.</li><li>Add the client you are quoting.</li><li>Add line items with quantity, price, discount and tax.</li><li>Set the validity period, optionally add scope of work and exclusions, pick a template, and download the PDF.</li></ol>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $quoteFaqs))                    . self::toolCta('quotations')                    . '<p>Related: <a href="/tools/invoice-generator">Invoice Generator</a> · <a href="/tools/purchase-order-generator">Purchase Order Generator</a></p>'                    . $nav . '</main>',            ],        ];
    }

    // ── Credit Note Generator ─────────────────────────────────────

    private static function creditNotePages(string $nav): array
    {
        $creditNoteFaqs = [            ['Is the VenQore credit note generator really free?', 'Yes. Creating and downloading a PDF credit note is completely free, with no signup, no watermark and no limit on how many you generate.'],            ['What is the difference between a credit note and a refund?', 'A credit note is a document — it records that you owe the customer an amount and states why. A refund is the actual money movement. A single credit note can result in a cash refund, store credit, or an offset against a future invoice; the document and the payment are two separate things.'],            ['Do I need a credit note for every return?', 'It is best practice whenever a return, refund, or price correction affects an invoice you already issued, since it creates a paper trail for both sides. Purely internal stock adjustments with no customer-facing invoice usually do not need one.'],            ['Is a credit note the same as a negative invoice?', 'Conceptually similar but not the same document. A proper credit note explicitly references the original invoice it is correcting or reversing and states a reason, which is how accounting systems and auditors distinguish it from an invoice that simply has a negative total.'],            ['Why does this tool require the original invoice number?', 'A credit note with no reference to what it is crediting is not auditable — it is just a discount slip. Requiring the original invoice number keeps every credit note usable as a real accounting record.'],            ['Can I save my company details for next time?', 'Yes — your company name, address, logo and tax ID are saved in your browser (separately from the invoice tool) so you do not have to retype them next time. Nothing is sent to or stored on our servers until you click Download.'],        ];
        return [            'tools.credit-note' => [                'title'       => 'Free Credit Note Generator — PDF, No Watermark | VenQore',                'description' => 'Create a professional PDF credit note free online. References the original invoice, records the reason for credit, multiple templates and currencies. No signup, no watermark.',                'keywords'    => 'free credit note generator, credit note template pdf, credit memo generator, credit note maker online, credit note for returns and refunds',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Credit Note Generator',                                url('/tools/credit-note-generator'),                                'Free online credit note generator that references the original invoice and records the reason for credit, producing an unwatermarked PDF.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Credit Note Generator', 'url' => url('/tools/credit-note-generator')],                            ]),                            self::faqLd($creditNoteFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to create a free PDF credit note',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Add your business details', 'text' => 'Enter your business name, address, and optionally a logo and tax ID. These are saved in your browser for next time.'],                                    ['@type' => 'HowToStep', 'name' => 'Add the client', 'text' => 'Enter the name and address of the customer you are issuing the credit to.'],                                    ['@type' => 'HowToStep', 'name' => 'Reference the original invoice and reason', 'text' => 'Enter the original invoice number (required), optionally its date, and select the reason for the credit — product return, damaged goods, pricing error, order cancellation, goodwill, or other.'],                                    ['@type' => 'HowToStep', 'name' => 'Add line items and download', 'text' => 'List each item being credited with quantity, unit price, and optional tax and discount, choose how the credit will be applied, then download the finished PDF.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Credit Note Generator</nav>'                    . '<h1>Free Credit Note Generator</h1>'                    . '<p><strong>Create a professional, unwatermarked PDF credit note in minutes.</strong> A credit note documents money owed back to a customer — for a return, damaged goods, a pricing error, a cancelled order, or a goodwill gesture. Every credit note requires a reference to the original invoice and a stated reason, so it holds up as a real accounting record rather than just a discount slip. No signup required, and your business profile is saved locally so you never retype it.</p>'                    . '<h2>What is a credit note, and when should I issue one?</h2>'                    . '<p>A credit note (sometimes called a credit memo) is a document a seller issues to a buyer to reduce the amount owed on a previous invoice, or to record an amount owed back to the buyer. You issue one whenever a customer returns goods, receives damaged or defective items, was overcharged due to a pricing error, cancels an order after being invoiced, or when you want to extend a goodwill credit. It is the accounting-side record of the correction — separate from however the credit is actually settled.</p>'                    . '<h2>Credit note vs. refund — what is the difference?</h2>'                    . '<p>A <strong>credit note is a document</strong>; a <strong>refund is the actual movement of money</strong>. Issuing a credit note does not, by itself, move any cash. The credit note simply states that a certain amount is owed back to the customer and why. What happens next — a refund to the original payment method, store credit, or an offset against a future invoice — is a separate step, recorded on the credit note as the "credit method" but settled independently. This is exactly why a credit note is not the same as a negative invoice: a negative invoice is just a number, while a credit note is a structured, auditable record with a reason and a reference.</p>'                    . '<h2>Why the original invoice reference matters</h2>'                    . '<p>A credit note that does not reference the invoice it corrects cannot be reconciled against your books. Auditors, accountants, and even your own future self need to be able to trace every credit note back to the sale it adjusts. That is why this tool requires an original invoice number before it will generate a PDF — it is a hard requirement, not an optional nicety.</p>'                    . '<h2>What you can customize</h2>'                    . '<ul><li>Business logo, name, address, email, phone and tax ID</li>'                    . '<li>Client name, address and email</li>'                    . '<li>Required original invoice number, with an optional original invoice date</li>'                    . '<li>Required reason for credit — Product Return, Damaged/Defective Goods, Pricing Error, Order Cancellation, Goodwill Credit, or Other with a free-text description</li>'                    . '<li>Optional credit method — refund to original payment method, store credit, applied to a future invoice, or other</li>'                    . '<li>Unlimited line items with per-line quantity, unit price, discount % and tax %, totaled as "Total Credit" — never framed as an amount due</li>'                    . '<li>Four visual templates: Clean, Modern, Classic, Compact</li>'                    . '<li>10 supported currencies</li></ul>'                    . '<h2>How to create a credit note</h2>'                    . '<ol><li>Add your business details — saved locally for next time.</li><li>Add the client you are issuing the credit to.</li><li>Enter the original invoice number and the reason for the credit.</li><li>Add line items, optionally set a credit method, and download the PDF.</li></ol>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $creditNoteFaqs))                    . self::toolCta('credit notes')                    . '<p>Related: <a href="/tools/invoice-generator">Invoice Generator</a> · <a href="/tools/barcode-generator">Barcode Generator</a></p>'                    . $nav . '</main>',            ],        ];
    }

    // ── Product CSV Cleaner ─────────────────────────────────────

    private static function csvCleanerPages(string $nav): array
    {
        $csvFaqs = [            ['Is the VenQore Product CSV Cleaner really free?', 'Yes. Uploading or pasting a product CSV, reviewing the cleanup report, and downloading the cleaned file are all completely free, with no signup and no watermark.'],            ["Why won't Shopify or WooCommerce accept my product CSV?", 'The most common reasons an import gets rejected are a missing required column (like SKU or price), a price field containing a currency symbol or thousands separator such as "$19.99" or "1,200.00" instead of a plain number, duplicate SKUs across rows, or an invalid barcode/UPC/EAN check digit. This tool detects and reports every one of these before you re-upload.'],            ['How do I fix duplicate SKUs before importing?', 'Run your file through the cleaner — it flags every row sharing a SKU value so you can see exactly which products collide. From there you can rename SKUs manually, or opt in to auto-generate a unique SKU from the product name for any row missing one.'],            ['What format should product prices be in for CSV import?', 'A plain decimal number with no currency symbol, no thousands separator, and a period as the decimal point — e.g. 19.99, not "$19.99" or "1,200.00" or "19,99". The cleaner automatically strips symbols and normalizes both US and European number formats into this plain form.'],            ['Does this tool store or upload my product data anywhere?', 'No. The file or pasted text is parsed in memory for the single request and never written to a database or logged. Nothing about your catalog leaves that one request/response cycle.'],            ['How does column auto-detection work?', 'The tool matches your header row against a list of common aliases per field — for example "Regular Price", "Unit Price" and "Price" all map to the price field, and "Item Code", "Product Code" and "SKU" all map to SKU. If it guesses a column wrong, you can override the mapping with a dropdown before downloading.'],            ['What counts as an invalid barcode?', 'If a barcode/UPC/EAN/GTIN column is detected, each value is run through the same check-digit validation VenQore\'s barcode tools use — an 8, 12, 13 or 14-digit GTIN whose last digit does not match what the standard formula computes is flagged as invalid, since a real scanner would likely reject or misread it.'],            ['Is there a row limit?', 'Yes — up to 5,000 rows per file to keep this a fast, free tool rather than a bulk data pipeline. For larger catalogs, VenQore customers can use the built-in product import inside the app, which has no such cap.'],        ];
        return [            'tools.csv-cleaner' => [                'title'       => 'Free Product CSV Cleaner — Fix Shopify/Woo Imports | VenQore',                'description' => 'Upload or paste a messy product CSV and get a cleaned, validated file back. Fixes malformed prices, duplicate SKUs, missing SKUs and invalid barcodes. Free, no signup.',                'keywords'    => 'product csv cleaner, fix shopify csv import, woocommerce csv cleaner, clean product csv, duplicate sku finder, csv price format fix, product import validator',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Product CSV Cleaner',                                url('/tools/product-csv-cleaner'),                                'Free online tool that parses a Shopify, WooCommerce or generic product CSV export, auto-detects columns, normalizes malformed prices, flags missing and duplicate SKUs, validates barcode check digits, and produces a cleaned, downloadable CSV after review.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Product CSV Cleaner', 'url' => url('/tools/product-csv-cleaner')],                            ]),                            self::faqLd($csvFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to clean a product CSV before importing',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Upload or paste your CSV', 'text' => 'Upload a .csv file (up to 5MB) or paste raw CSV text copied from a spreadsheet.'],                                    ['@type' => 'HowToStep', 'name' => 'Review the detected columns', 'text' => 'The tool auto-detects which column is Name, SKU, Price, Barcode, Quantity, Category and Description. Override any guess with a dropdown.'],                                    ['@type' => 'HowToStep', 'name' => 'Review the issue report', 'text' => 'See a breakdown of malformed prices, missing SKUs, duplicate SKUs, invalid barcodes and duplicate product listings, plus a preview of the first cleaned rows.'],                                    ['@type' => 'HowToStep', 'name' => 'Download the cleaned CSV', 'text' => 'Once the mapping and fixes look right, download the cleaned file ready to re-upload to Shopify, WooCommerce or your platform of choice.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Product CSV Cleaner</nav>'                    . '<h1>Free Product CSV Cleaner</h1>'                    . '<p><strong>Upload or paste a messy product CSV export and get back a cleaned, validated version</strong> — plus a clear report of exactly what was found and fixed. Built for Shopify, WooCommerce and generic spreadsheet exports. Auto-detects your columns, normalizes malformed prices, flags missing and duplicate SKUs, validates barcode check digits, and catches likely duplicate listings, all before you re-upload. No signup, no watermark, nothing stored.</p>'                    . '<h2>What it checks and fixes</h2>'                    . '<ul><li>Missing SKU — flagged, with an optional auto-generated SKU from the product name</li>'                    . '<li>Duplicate SKU — every row sharing a SKU value is flagged</li>'                    . '<li>Malformed price — currency symbols and thousands separators like "$19.99" or "1,200.00" are normalized to a plain decimal; unparseable values are flagged</li>'                    . '<li>Negative or zero price — surfaced as a warning, since free items are sometimes intentional</li>'                    . '<li>Invalid barcode — UPC/EAN/GTIN check digits are validated using the same logic as VenQore\'s barcode tools</li>'                    . '<li>Duplicate product name + category combinations — flagged as possible duplicate listings</li>'                    . '<li>Whitespace and casing cleanup — leading/trailing spaces trimmed, repeated internal spaces collapsed</li>'                    . '<li>Empty rows — silently skipped, not flagged as errors</li></ul>'                    . '<h2>Why Shopify or WooCommerce rejects a CSV import</h2>'                    . '<p>Import rejections almost always come down to a handful of repeat offenders: a price column that still has a currency symbol or thousands separator in it, a SKU column with blanks or duplicate values, or a barcode column with a typo that breaks the check digit. This tool runs all of those checks in one pass and shows you the exact rows and reasons before you spend time re-uploading a file that will bounce again.</p>'                    . '<h2>How column auto-detection works</h2>'                    . '<p>Common header variations are matched automatically — "Regular Price", "Unit Price" and "Price" all map to the price field; "Item Code", "Product Code" and "SKU" all map to SKU; "UPC", "EAN" and "GTIN" all map to barcode. If a guess is wrong, override it with a dropdown before downloading — nothing is finalized until you confirm the mapping.</p>'                    . '<h2>How to clean a product CSV</h2>'                    . '<ol><li>Upload a .csv file or paste raw CSV text.</li><li>Review and, if needed, correct the auto-detected column mapping.</li><li>Review the issue report and preview of cleaned rows.</li><li>Download the cleaned CSV, ready to re-import.</li></ol>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $csvFaqs))                    . self::toolCta('clean product data')                    . '<p>Related: <a href="/tools/sku-generator">Bulk SKU Generator</a> · <a href="/tools/barcode-validator">Barcode Validator</a></p>'                    . $nav . '</main>',            ],        ];
    }

    // ── POS ROI Calculator ─────────────────────────────────────

    private static function posRoiPages(string $nav): array
    {
        $posRoiFaqs = [            ['How do I calculate ROI on a POS system?', 'Add up what the new system actually saves you each month — typically less shrinkage/inventory loss from better tracking, plus staff or owner time no longer spent on manual reconciliation and reporting — then subtract the new system\'s net monthly cost (its subscription minus whatever you were already paying for a register or the old system). That gives a net monthly impact. Divide any one-time setup or hardware cost by that monthly impact to get a breakeven point in months. If the monthly impact is negative, the system is costing more than it currently saves, and there is no breakeven at those inputs.'],            ['What hidden costs does a POS system save on?', 'The two most commonly underestimated ones are shrinkage (theft, spoilage and unrecorded errors a manual or basic system can\'t catch) and staff/owner time spent reconciling registers, re-entering sales into spreadsheets and building reports by hand. A smaller, harder-to-quantify factor is lost sales from stockouts or slow manual checkout during busy periods.'],            ['How long does it take a POS system to pay for itself?', 'It depends entirely on your current shrinkage rate, how much staff time you spend on manual admin, and the system\'s price — there is no universal answer. A busy shop with high shrinkage and heavy manual bookkeeping can break even in weeks. A very small operation with tight losses already and minimal admin overhead may take much longer, or may not see a positive return on a paid system at all.'],            ['Is this calculator biased toward showing a positive result?', 'No — it is deliberately built so entering low shrinkage rates, low admin overhead and low current costs produces a marginal or negative result, honestly. All assumptions (shrinkage reduction %, time saved, monthly cost) are editable, and the defaults are conservative rather than optimistic.'],            ['Is this calculator free?', 'Yes. Every calculation runs in your browser — no signup, no email required, and nothing is sent to a server.'],        ];
        return [            'tools.pos-roi' => [                'title'       => 'Free POS ROI Calculator | VenQore',                'description' => 'Work out whether a POS system pays for itself. Enter your own shrinkage rate, admin hours and costs — get an honest monthly savings, breakeven and 12/36-month projection. Free, no signup.',                'keywords'    => 'pos roi calculator, pos system cost calculator, is a pos system worth it, pos breakeven calculator, retail shrinkage calculator, pos payback period',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore POS ROI Calculator',                                url('/tools/pos-roi-calculator'),                                'Free online calculator estimating whether a POS system pays for itself, using editable inputs for shrinkage rate, admin time, lost sales and system costs, with monthly savings, breakeven and 12/36-month projections computed entirely client-side.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'POS ROI Calculator', 'url' => url('/tools/pos-roi-calculator')],                            ]),                            self::faqLd($posRoiFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to calculate POS ROI',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Enter your current state', 'text' => 'Fill in monthly revenue, your current shrinkage/loss rate, hours spent on manual admin per week, the value of that time, and any existing POS/register cost.'],                                    ['@type' => 'HowToStep', 'name' => 'Enter the new system\'s cost and expected improvement', 'text' => 'Enter the new POS system\'s monthly cost, one-time setup cost, and realistic (not inflated) estimates for shrinkage reduction and admin hours saved.'],                                    ['@type' => 'HowToStep', 'name' => 'Read the result honestly', 'text' => 'The calculator shows monthly savings, breakeven point, and 12/36-month net impact — including negative results if your inputs do not support a positive return.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; POS ROI Calculator</nav>'                    . '<h1>Free POS ROI Calculator</h1>'                    . '<p><strong>Estimate whether switching to (or adopting) a POS system actually pays for itself</strong>, using your own numbers for shrinkage, admin time and cost — not generic industry claims. Every assumption is editable and the defaults are conservative. If your inputs point to a negative or marginal return, the calculator shows that honestly rather than hiding it. Free, entirely client-side, no signup.</p>'                    . '<h2>What drives POS ROI</h2>'                    . '<p>Four factors matter most: <strong>shrinkage reduction</strong> from better stock tracking and fewer manual entry errors, <strong>staff/owner time savings</strong> from automated reconciliation and reporting, <strong>faster checkout</strong> that can reduce walkaways during busy periods, and <strong>reduced pricing errors</strong> from centralized pricing instead of drifting shelf tags and register overrides.</p>'                    . '<h2>The math</h2>'                    . '<p>Monthly gain = shrinkage $ saved + time $ saved (+ any lost-sales $ recovered, which defaults to $0 unless you set a recovery rate). Net new monthly cost = new POS monthly cost − old POS monthly cost. Net monthly impact = monthly gain − net new monthly cost. Breakeven (months) = one-time setup cost ÷ net monthly impact, only defined when the impact is positive.</p>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $posRoiFaqs))                    . self::toolCta('inventory tracking and reporting that a manual system can\'t match')                    . '<p>Related: <a href="/tools/margin-calculator">Profit Margin & Markup Calculator</a> · <a href="/tools/inventory-health">Inventory Health Toolkit</a></p>'                    . $nav . '</main>',            ],        ];
    }

    // ── Payment Processing Fee Calculator ─────────────────────────────────────

    private static function paymentFeePages(string $nav): array
    {
        $paymentFeeFaqs = [            ['Why is my effective payment processing rate higher than the advertised rate?', 'Advertised rates usually quote only the percentage component (e.g. "2.9%") and leave out the fixed per-transaction fee, any monthly/plan fees, and often a higher rate for card-not-present (online/keyed-in) transactions versus card-present (in-person) ones. Your true effective rate is total fees divided by total volume processed, which is always higher than the headline percentage once fixed fees are included — especially on smaller transactions.'],            ['Does transaction size affect which payment processor is cheapest?', 'Yes, significantly. Every processor charges a percentage plus a small fixed fee per transaction. On a small ticket, the fixed fee is a large share of the sale and can dominate the total cost; on a large ticket, that same fixed fee is nearly irrelevant and the percentage rate decides the winner. A processor with a lower percentage but higher fixed fee can lose at small ticket sizes and win at large ones, or vice versa — always compare using your own average ticket size.'],            ["What's the difference between card-present and online processing fees?", 'Card-present transactions (tapping, dipping or swiping a physical card) are lower risk for the processor since the card is physically verified, so rates are typically lower. Card-not-present transactions (online checkout, phone orders, manually keyed-in numbers) carry more fraud risk, so processors typically charge a higher percentage for those. Businesses taking both in-person and online payments should expect two different effective rates from the same processor.'],            ['Are the default rates in this calculator current?', 'No — treat them as illustrative, long-stable baseline figures only, not a guarantee of current pricing. Payment processor rates change over time and vary by plan, business type and country. Every rate field is editable; replace the defaults with your actual rate sheet before making a decision, and verify current rates directly with each processor.'],            ['Is this calculator really free?', 'Yes. Every calculation — single transaction, monthly volume comparison, and cheapest-processor ranking — runs in your browser. No signup, no email required, nothing sent to a server.'],        ];
        return [            'tools.payment-fee' => [                'title'       => 'Free Payment Processing Fee Calculator | VenQore',                'description' => 'Compare Stripe, Square, PayPal, Clover and Shopify Payments fees side by side for a single transaction or your monthly volume. Every rate is editable. Illustrative rates — verify current pricing. Free, no signup.',                'keywords'    => 'payment processing fee calculator, credit card processing fees, stripe vs square fees, payment processor comparison, merchant fee calculator, card processing rate calculator',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Payment Processing Fee Calculator',                                url('/tools/payment-fee-calculator'),                                'Free online calculator comparing the effective processing cost of Stripe, Square, PayPal, Clover and Shopify Payments for a single transaction or monthly transaction volume, with fully editable rates. Default rates are illustrative baselines only — verify current pricing with each processor.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Payment Fee Calculator', 'url' => url('/tools/payment-fee-calculator')],                            ]),                            self::faqLd($paymentFeeFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to compare payment processing fees',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Review or edit processor rates', 'text' => 'Each processor lists an editable percentage rate, fixed fee per transaction and optional monthly fee. Defaults are illustrative baselines — replace them with your actual rate sheet if you have one.'],                                    ['@type' => 'HowToStep', 'name' => 'Choose single transaction or monthly volume mode', 'text' => 'Single transaction mode compares the fee on one sale amount; monthly volume mode compares total fees across your average ticket size and transaction count for the month.'],                                    ['@type' => 'HowToStep', 'name' => 'Read the side-by-side comparison', 'text' => 'Each processor shows its fee and net amount received (single mode) or total monthly fees, effective rate and net revenue (monthly mode), with the cheapest option highlighted.'],                                    ['@type' => 'HowToStep', 'name' => 'Verify current rates before deciding', 'text' => 'Because processor pricing changes over time and by plan, confirm the current published rate directly with each processor before switching or signing a contract.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Payment Processing Fee Calculator</nav>'                    . '<h1>Free Payment Processing Fee Calculator</h1>'                    . '<p><strong>Compare the effective cost of Stripe, Square, PayPal, Clover and Shopify Payments side by side</strong>, for either a single transaction or your monthly transaction volume. Every rate — percentage, fixed fee and optional monthly fee — is fully editable, so you can plug in your actual rate sheet for an accurate comparison. Runs entirely in your browser, free, no signup.</p>'                    . '<p><strong>Important: the default rates shown are approximate and illustrative only, based on well-known, long-stable published baseline figures.</strong> Payment processor pricing changes over time and varies by plan tier, card-present vs. online transactions, business type and country. Always verify current rates directly with each processor before making a decision — do not treat the defaults in this tool as guaranteed-current facts.</p>'                    . '<h2>Why comparing "just the percentage" is misleading</h2>'                    . '<p>Every processor charges a percentage of the sale plus a small fixed fee per transaction. The fixed fee is the same dollar amount regardless of sale size, so it is a much bigger relative burden on small tickets than on large ones. A processor advertising the lowest percentage is not automatically the cheapest option for your business — the fixed-fee component can flip the ranking entirely depending on your average transaction size.</p>'                    . '<h2>Worked example</h2>'                    . '<p>Processor A charges 2.6% + $0.10 per transaction; Processor B charges 2.9% + $0.30, both over 100 transactions/month. At a $10 average ticket: A = 100 × (10×0.026 + 0.10) = $36.00, B = 100 × (10×0.029 + 0.30) = $59.00 — A wins by $23.00, since the fixed-fee gap dominates at a small ticket size. At a $200 average ticket: A = 100 × (200×0.026 + 0.10) = $530.00, B = 100 × (200×0.029 + 0.30) = $610.00 — A still wins, but the fixed-fee gap now matters far less relative to total volume, and different rate pairs can flip the ranking entirely at small ticket sizes.</p>'                    . '<h2>Card-present vs. card-not-present rates</h2>'                    . '<p>In-person card payments (tap, dip or swipe) are lower risk for the processor since the card is physically verified, so rates are typically lower. Online checkout, phone orders and manually keyed-in card numbers carry more fraud risk and are typically charged a higher percentage. Businesses taking both channels should model each separately rather than relying on one blended rate.</p>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $paymentFeeFaqs))                    . self::toolCta('per-sale processing fee tracking')                    . '<p>Related: <a href="/tools/margin-calculator">Profit Margin & Markup Calculator</a> · <a href="/tools/pos-roi-calculator">POS ROI Calculator</a></p>'                    . $nav . '</main>',            ],        ];
    }

    // ── Recipe Costing Calculator ─────────────────────────────────────

    private static function foodCostPages(string $nav): array
    {
        $foodCostFaqs = [            ['What is a good food cost percentage for a restaurant?', 'It varies by segment, but a commonly cited general benchmark is roughly 28–35% of the menu price. Quick-service and fast-casual concepts often target the lower end (around 25–30%), fine dining sometimes runs higher (30–38%), and bar/beverage programs typically run much lower (15–24%) since pour costs are cheap relative to drink prices. These are general guidance, not fixed rules — your target should reflect labor cost, rent and concept.'],            ['How do I price a menu item?', 'Cost out the recipe by summing every ingredient\'s cost contribution, optionally add a waste/spoilage allowance, divide by the number of portions the recipe yields to get cost per portion, then divide that by your target food-cost percentage. Formula: suggested price = cost per portion ÷ (target food-cost % ÷ 100). Example: a $3.00 cost-per-portion dish at a 30% target food cost prices at 3.00 ÷ 0.30 = $10.00.'],            ['What is a waste/spoilage allowance and why does it matter?', 'It\'s a percentage added on top of raw ingredient cost to account for real kitchen losses — trim waste, spillage, over-portioning and spoilage — that never make it into a plated portion. A typical allowance is 5–10%. Ignoring it understates true recipe cost and results in menu prices that undershoot your actual target food-cost percentage once real-world waste is accounted for.'],            ['How are food cost percentage and gross margin related?', 'They are complementary and always add to 100% of the menu price: food-cost % + gross margin % = 100%. A dish with a 30% food cost has a 70% gross margin. See the Profit Margin & Markup Calculator for the same relationship applied to general retail pricing.'],            ['Does this tool handle unit conversion between purchase size and recipe usage?', 'Yes — enter the recipe quantity in whatever unit fits your prep sheet (e.g. grams) and the purchase cost in whatever unit you buy it in (e.g. per kilogram); the tool converts automatically. It supports weight (g, kg, oz, lb) and volume (ml, L, fl oz) conversions, including across metric and imperial, plus a plain "each" unit for counted items. Cross-dimension conversions, like grams to fluid ounces, are flagged rather than guessed.'],            ['Is this calculator free?', 'Yes. Every calculation — unit conversion, cost per portion, waste allowance, target food-cost % pricing, and the multi-recipe summary with CSV export — runs entirely in your browser. No signup, no email required.'],        ];
        return [            'tools.food-cost' => [                'title'       => 'Free Recipe Costing Calculator (Food Cost %) | VenQore',                'description' => 'Cost a recipe ingredient by ingredient with automatic unit conversion, get cost per portion, a suggested menu price for your target food-cost %, and the food-cost % of any price. Free, no signup.',                'keywords'    => 'food cost calculator, recipe costing calculator, restaurant food cost percentage, menu pricing calculator, plate cost calculator, ideal food cost',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Recipe Costing Calculator',                                url('/tools/food-cost-calculator'),                                'Free online calculator that costs a recipe from its ingredients with automatic unit conversion, computes cost per portion including an optional waste/spoilage allowance, and suggests a menu price for a target food-cost percentage — or the food-cost percentage of any price — with a multi-recipe summary table and CSV export, entirely client-side.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Recipe Costing Calculator', 'url' => url('/tools/food-cost-calculator')],                            ]),                            self::faqLd($foodCostFaqs),                            [                                '@type' => 'HowTo',                                'name'  => 'How to cost a recipe and price a menu item',                                'step'  => [                                    ['@type' => 'HowToStep', 'name' => 'Add each ingredient', 'text' => 'Enter every ingredient\'s recipe quantity and unit, plus its purchase cost and purchase unit — the tool converts between them automatically.'],                                    ['@type' => 'HowToStep', 'name' => 'Apply a waste allowance', 'text' => 'Optionally add a waste/spoilage percentage on top of raw ingredient cost to reflect real kitchen losses.'],                                    ['@type' => 'HowToStep', 'name' => 'Divide by portions', 'text' => 'Enter how many portions the recipe yields to get an exact cost per portion.'],                                    ['@type' => 'HowToStep', 'name' => 'Solve for a menu price', 'text' => 'Enter a target food-cost percentage to get a suggested price, or enter a price to see its resulting food-cost percentage.'],                                ],                            ],                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Recipe Costing Calculator</nav>'                    . '<h1>Free Recipe Costing Calculator</h1>'                    . '<p><strong>Add each ingredient with its recipe quantity and purchase cost, and the calculator converts units automatically</strong> (grams to kilograms, ounces to pounds, and more) to compute exact cost contribution. It totals the recipe, applies an optional waste/spoilage allowance, divides by portions for cost per portion, then suggests a menu price for your target food-cost percentage — or tells you the food-cost percentage of a price you already charge. Includes a multi-recipe summary table with CSV export. Free, entirely client-side, no signup.</p>'                    . '<h2>What is food cost percentage?</h2>'                    . '<p>Food cost percentage is the portion of a menu item\'s selling price that goes toward ingredients: food cost % = cost per portion ÷ menu price × 100. It is the primary lever restaurants use to keep menu pricing aligned with ingredient cost.</p>'                    . '<h2>Typical target ranges by segment</h2>'                    . '<p>General industry benchmarks, not fixed rules: quick-service/fast-casual often run 25–30% food cost, casual/full-service commonly target 28–35%, fine dining sometimes runs 30–38%, and bar/beverage programs often run 15–24%. Actual targets depend on labor cost, rent and concept.</p>'                    . '<h2>Worked example</h2>'                    . '<p>200g of flour used, purchased at $2.00/kg: 200g = 0.2kg, so cost contribution = 0.2 × $2.00 = $0.40. With three more ingredients totaling $1.20, raw recipe cost is $1.60. Apply a 10% waste allowance: $1.60 × 1.10 = $1.76. Over 4 portions, cost per portion = $1.76 ÷ 4 = $0.44. At a 30% target food cost, suggested price = $0.44 ÷ 0.30 = $1.47 (rounded).</p>'                    . '<h2>Food cost % and gross margin are complementary</h2>'                    . '<p>Food-cost % + gross margin % = 100% of the menu price. A 30% food cost is exactly a 70% gross margin on that item — the same relationship the <a href="/tools/margin-calculator">Profit Margin &amp; Markup Calculator</a> solves for any product.</p>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $foodCostFaqs))                    . self::toolCta('automatic per-sale food cost tracking')                    . '<p>Related: <a href="/tools/margin-calculator">Profit Margin & Markup Calculator</a> · <a href="/tools/inventory-health">Inventory Health Toolkit</a></p>'                    . $nav . '</main>',            ],        ];
    }

    private static function barcodeLabelSheetPages(string $nav): array
    {
        $faqs = [            ['Is the barcode label sheet generator really free?', 'Yes. Building and downloading a print-ready PDF of barcode inventory labels is completely free, with no signup and no watermark, for any number of products within the rate limit.'],            ['How is this different from the barcode print-sheet on the Barcode Generator page?', 'That tool repeats one barcode value many times. This tool prints a batch of different products at once, each getting its own barcode, name and optional price — useful for labelling a whole shipment or shelf of new inventory in one pass.'],            ['What barcode formats are supported?', 'Any format supported by the main Barcode Generator — Code128, Code39, Code93, EAN-13, EAN-8, UPC-A, UPC-E, ITF-14 and Codabar — chosen per row.'],            ['What label sizes are supported?', 'Small thermal inventory-label sizes for direct label printers, plus Avery-compatible A4 and Letter sheet grids (21, 24 or 65 labels per sheet) for a standard printer.'],        ];
        return [            'tools.barcode-label' => [                'title'       => 'Free Barcode Label Sheet Generator | VenQore',                'description' => 'Print Avery-compatible barcode inventory labels for a whole batch of different products at once, each with a real scannable barcode. Free, no signup.',                'keywords'    => 'barcode label generator, inventory label sheet, avery barcode labels, print product barcodes free',                'jsonld'      => [                    [                        '@context' => 'https://schema.org',                        '@graph'   => [                            self::softwareApplicationLd(                                'VenQore Barcode Label Sheet Generator',                                url('/tools/barcode-label-generator'),                                'Free online generator for Avery-compatible barcode inventory label sheets, one scannable barcode per product.'                            ),                            self::breadcrumbLd([                                ['name' => 'Home', 'url' => url('/')],                                ['name' => 'Tools', 'url' => url('/tools')],                                ['name' => 'Barcode Label Sheet Generator', 'url' => url('/tools/barcode-label-generator')],                            ]),                            self::faqLd($faqs),                        ],                    ],                ],                'static_html' => '<main style="font-family:system-ui,sans-serif;max-width:760px;margin:2rem auto;padding:0 1rem;line-height:1.6">'                    . '<nav aria-label="breadcrumb"><a href="/">Home</a> &rsaquo; <a href="/tools">Tools</a> &rsaquo; Barcode Label Sheet Generator</nav>'                    . '<h1>Free Barcode Label Sheet Generator</h1>'                    . '<p><strong>Label a whole batch of different products at once.</strong> Each row gets its own real, scannable barcode, product name and optional price, printed on Avery-compatible or thermal label sheets. Free, unlimited, no signup, no watermark.</p>'                    . '<h2>Manual entry or bulk paste</h2>'                    . '<p>Add rows one at a time, or paste a CSV-style list (name,value,format,price) to populate the whole batch instantly.</p>'                    . '<h2>Frequently asked questions</h2>'                    . implode('', array_map(fn ($qa) => "<p><strong>{$qa[0]}</strong> {$qa[1]}</p>", $faqs))                    . self::toolCta('barcode labels on every product automatically')                    . '<p>Related: <a href="/tools/barcode-generator">Barcode Generator</a> · <a href="/tools/price-tag-generator">Price Tag Generator</a></p>'                    . $nav . '</main>',            ],        ];
    }
